/**
 * Sumber tunggal warna status Motor Tarikan.
 * DISAMAKAN PERSIS dengan Document States (meta.states) doctype "Motor Tarikan"
 * — warna indikator yang dipakai Frappe (form & list) untuk field `status_unit`.
 * Dipakai untuk pill status di list card portal.
 */

// status_unit → nama warna Frappe (persis dari Document States doctype).
const STATE_COLOR = {
	'Stok Tebus': 'blue',
	'Proses Inspeksi': 'red',
	'Stok AYDA': 'orange',
	'Dalam Repair': 'purple',
	'Keluar Lelang': 'green',
	'Keluar BBG': 'green',
	'Keluar Pinjam': 'yellow',
	'Keluar Tebus Selesai': 'green',
	'Stok Titipan': 'cyan',
	'Keluar Titipan': 'light-blue',
}

// Daftar status untuk picker filter (urut sesuai opsi field status_unit).
export const STATUS_OPTIONS = [
	'Stok Tebus',
	'Proses Inspeksi',
	'Stok AYDA',
	'Dalam Repair',
	'Keluar Lelang',
	'Keluar BBG',
	'Keluar Pinjam',
	'Keluar Tebus Selesai',
	'Stok Titipan',
	'Keluar Titipan',
]

// Tebak warna untuk status tak terdaftar — meniru frappe.utils.guess_colour.
function guessColor(status) {
	const s = String(status || '')
	if (/Proses|Inspeksi|Repair/i.test(s)) return 'orange'
	if (/Keluar/i.test(s)) return 'green'
	if (/Stok/i.test(s)) return 'blue'
	return 'gray'
}

export function statusColor(status) {
	return STATE_COLOR[status] || guessColor(status)
}

// Pill (bg + teks) untuk badge status di card.
const PILL = {
	gray: 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	blue: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	'light-blue': 'bg-ui-surface-sky-200 text-ui-ink-sky-800',
	cyan: 'bg-ui-surface-cyan-100 text-ui-ink-cyan-700',
	orange: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	green: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	red: 'bg-ui-surface-red-100 text-ui-ink-red-700',
	yellow: 'bg-ui-surface-yellow-100 text-ui-ink-yellow-800',
	purple: 'bg-ui-surface-purple-100 text-ui-ink-purple-700',
}
export function statusPillClass(status) {
	return PILL[statusColor(status)] || PILL.gray
}

// Titik (border lingkaran) untuk picker status di sheet filter.
const DOT = {
	gray: 'border-ui-line-gray-400',
	blue: 'border-ui-line-blue-500',
	'light-blue': 'border-ui-line-sky-500',
	cyan: 'border-ui-line-cyan-500',
	orange: 'border-ui-line-orange-500',
	green: 'border-ui-line-green-500',
	red: 'border-ui-line-red-500',
	yellow: 'border-ui-line-yellow-500',
	purple: 'border-ui-line-purple-500',
}
export function statusDotClass(status) {
	return DOT[statusColor(status)] || DOT.gray
}

// ---- Indikator UMUR STOK (aging) -------------------------------------------
// PERSIS list-view desk (motor_tarikan_list.js, design §13.3):
//   0–30 hijau · 31–60 kuning · 61–90 oranye · >90 merah. Label "Umur {age}d".
export function umurColor(age) {
	const a = Number(age) || 0
	if (a <= 30) return 'green'
	if (a <= 60) return 'yellow'
	if (a <= 90) return 'orange'
	return 'red'
}
export function umurPillClass(age) {
	return PILL[umurColor(age)] || PILL.gray
}
export function umurLabel(age) {
	return `Umur ${Number(age) || 0}d`
}

// ---- Indikator DOCSTATUS (submittable) -------------------------------------
// Seperti Frappe core: docstatus 0 = Draft, 2 = Cancelled. docstatus 1 (Submitted)
// = kondisi normal → tanpa badge.
export function docstatusLabel(ds) {
	if (ds === 0 || ds === '0') return 'Draft'
	if (ds === 2 || ds === '2') return 'Cancelled'
	return ''
}
export function docstatusPillClass(ds) {
	if (ds === 2 || ds === '2') return 'bg-ui-surface-red-100 text-ui-ink-red-700'
	if (ds === 0 || ds === '0') return 'bg-ui-surface-gray-100 text-ui-ink-gray-600'
	return ''
}
